/**
 * Extracts the parts of the globe-wallet contract interface that the backend
 * mirrors — `WalletError` discriminants and `@event`-tagged event payload
 * structs — straight from `contract/contracts/globe-wallet/src/lib.rs`, and
 * renders the generated TypeScript modules under `./generated/`.
 *
 * Used by `backend/scripts/gen-contract-spec.ts` (writes / `--check`s the
 * generated files) and by the Jest suite, which fails whenever the committed
 * generated output drifts from the contract source (issues #192, #193).
 */

export interface ContractErrorSpec {
  code: number;
  name: string;
  apiCode: string;
}

/** Wire-level kind of an event field, as decoded from its `ScVal`. */
export type FieldKind = string;

export interface EventFieldSpec {
  name: string;
  kind: FieldKind;
}

export interface EventSpec {
  event: string;
  struct: string;
  version: number;
  fields: EventFieldSpec[];
}

/** `SpendLimitExceeded` -> `SPEND_LIMIT_EXCEEDED`. */
export function toApiCode(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toUpperCase();
}

export function parseWalletErrors(source: string): ContractErrorSpec[] {
  const block = source.match(/pub enum WalletError\s*\{([^}]+)\}/s);
  if (!block) throw new Error("pub enum WalletError not found in contract source");
  const out: ContractErrorSpec[] = [];
  const variant = /^\s*([A-Za-z0-9_]+)\s*=\s*(\d+)\s*,?\s*$/gm;
  let m: RegExpExecArray | null;
  while ((m = variant.exec(block[1])) !== null) {
    out.push({ code: Number(m[2]), name: m[1], apiCode: toApiCode(m[1]) });
  }
  return out;
}

export function parseEventVersion(source: string): number {
  const m = source.match(/pub const EVENT_VERSION:\s*u32\s*=\s*(\d+);/);
  if (!m) throw new Error("EVENT_VERSION not found in contract source");
  return Number(m[1]);
}

/** Names of `#[contracttype]` fieldless integer enums (encoded as u32). */
function parseIntegerEnums(source: string): Set<string> {
  const names = new Set<string>();
  const re = /pub enum (\w+)\s*\{([^}]*)\}/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(source)) !== null) {
    if (m[1] === "WalletError") continue;
    const body = m[2].replace(/\/\/.*$/gm, "");
    if (/=\s*\d+/.test(body) && !/[({]/.test(body)) names.add(m[1]);
  }
  return names;
}

export function rustTypeToKind(rustType: string, intEnums: Set<string> = new Set()): FieldKind {
  const t = rustType.replace(/\s+/g, "");
  const generic = t.match(/^(Option|Vec)<(.+)>$/);
  if (generic) {
    return `${generic[1].toLowerCase()}<${rustTypeToKind(generic[2], intEnums)}>`;
  }
  if (/^BytesN<\d+>$/.test(t) || t === "Bytes") return "bytes";
  switch (t) {
    case "Address":
      return "address";
    case "String":
      return "string";
    case "Symbol":
      return "symbol";
    case "bool":
      return "bool";
    case "u32":
    case "i32":
      return "u32";
    case "u64":
    case "i64":
    case "u128":
    case "i128":
      return t;
    default:
      return intEnums.has(t) ? "u32" : "unknown";
  }
}

export function parseEventStructs(source: string): EventSpec[] {
  const version = parseEventVersion(source);
  const intEnums = parseIntegerEnums(source);
  const lines = source.split("\n");
  const out: EventSpec[] = [];
  for (let i = 0; i < lines.length; i++) {
    const head = lines[i].match(/^pub struct (\w+)\s*\{/);
    if (!head) continue;
    // Walk back over the attribute/doc block directly above the struct.
    let event: string | null = null;
    for (let j = i - 1; j >= 0; j--) {
      const l = lines[j].trim();
      if (!(l.startsWith("///") || l.startsWith("#["))) break;
      const tag = l.match(/@event\s+(\w+)/);
      if (tag) event = tag[1];
    }
    if (!event) continue;
    const fields: EventFieldSpec[] = [];
    for (let k = i + 1; k < lines.length && !/^\}/.test(lines[k]); k++) {
      const f = lines[k].match(/^\s*pub (\w+):\s*(.+?),\s*$/);
      if (f) fields.push({ name: f[1], kind: rustTypeToKind(f[2], intEnums) });
    }
    out.push({ event, struct: head[1], version, fields });
  }
  return out.sort((a, b) => a.event.localeCompare(b.event));
}

const HEADER =
  "// AUTO-GENERATED by backend/scripts/gen-contract-spec.ts from\n" +
  "// contract/contracts/globe-wallet/src/lib.rs — do not edit by hand.\n";

export function renderErrorsModule(errors: ContractErrorSpec[]): string {
  const rows = errors
    .map((e) => `  { code: ${e.code}, name: "${e.name}", apiCode: "${e.apiCode}" },`)
    .join("\n");
  return (
    HEADER +
    "\n" +
    "export interface GeneratedWalletError {\n  code: number;\n  name: string;\n  apiCode: string;\n}\n\n" +
    "export const GENERATED_WALLET_ERRORS: readonly GeneratedWalletError[] = [\n" +
    rows +
    "\n];\n"
  );
}

export function renderEventsModule(version: number, events: EventSpec[]): string {
  const body = events
    .map((e) => {
      const fields = e.fields.map((f) => `      { name: "${f.name}", kind: "${f.kind}" },`).join("\n");
      return (
        `  ${e.event}: {\n` +
        `    event: "${e.event}",\n` +
        `    struct: "${e.struct}",\n` +
        `    version: ${e.version},\n` +
        `    fields: [\n${fields}\n    ],\n` +
        `  },`
      );
    })
    .join("\n");
  return (
    HEADER +
    "\n" +
    "export interface GeneratedEventField {\n  name: string;\n  kind: string;\n}\n\n" +
    "export interface GeneratedEventSchema {\n  event: string;\n  struct: string;\n  version: number;\n  fields: readonly GeneratedEventField[];\n}\n\n" +
    `export const CONTRACT_EVENT_VERSION = ${version};\n\n` +
    "export const GENERATED_EVENT_SCHEMAS: Readonly<Record<string, GeneratedEventSchema>> = {\n" +
    body +
    "\n};\n"
  );
}

export const ERRORS_DOC_BEGIN = "<!-- BEGIN GENERATED ERROR CODES -->";
export const ERRORS_DOC_END = "<!-- END GENERATED ERROR CODES -->";

/** Canonical code table for `contract/docs/errors.md`. */
export function renderErrorsDocTable(errors: ContractErrorSpec[]): string {
  const rows = errors.map((e) => `| ${e.code} | \`${e.name}\` | \`${e.apiCode}\` |`).join("\n");
  return `${ERRORS_DOC_BEGIN}\n| Code | Variant | API Code |\n|:---|:---|:---|\n${rows}\n${ERRORS_DOC_END}`;
}

/** Replace the generated block in a markdown document (appends if missing). */
export function spliceGeneratedBlock(doc: string, block: string): string {
  const start = doc.indexOf(ERRORS_DOC_BEGIN);
  const end = doc.indexOf(ERRORS_DOC_END);
  if (start === -1 || end === -1) return `${doc.trimEnd()}\n\n${block}\n`;
  return doc.slice(0, start) + block + doc.slice(end + ERRORS_DOC_END.length);
}

/**
 * Snapshot compatibility rule (issue #193): every `name -> code` pair in the
 * committed snapshot must still exist unchanged, and any new code must be
 * appended above the snapshot's highest code. Returns human-readable
 * violations (empty when compatible).
 */
export function checkErrorSnapshot(
  errors: ContractErrorSpec[],
  snapshot: Record<string, number>
): string[] {
  const problems: string[] = [];
  const byName = new Map(errors.map((e) => [e.name, e.code]));
  const byCode = new Map(errors.map((e) => [e.code, e.name]));
  const maxSnap = Math.max(0, ...Object.values(snapshot));
  for (const [name, code] of Object.entries(snapshot)) {
    if (!byName.has(name)) problems.push(`${name} (${code}) was removed or renamed`);
    else if (byName.get(name) !== code) problems.push(`${name} changed from ${code} to ${byName.get(name)}`);
    else if (byCode.get(code) !== name) problems.push(`code ${code} is reused`);
  }
  const snapNames = new Set(Object.keys(snapshot));
  for (const e of errors) {
    if (!snapNames.has(e.name)) {
      if (e.code <= maxSnap) problems.push(`new variant ${e.name} uses code ${e.code} <= ${maxSnap}; append instead`);
      else problems.push(`new variant ${e.name} (${e.code}) is missing from error-codes.snapshot.json`);
    }
  }
  return problems;
}
